using System;
using System.Text.RegularExpressions;

namespace TheLair.TameAssistAddon.Core;

/// <summary>
/// Classify an untouched vanilla sign's placeholder separately from genuine
/// player text. Never replace arbitrary nonempty user-authored messages.
/// </summary>
public static class SignTextRules
{
    /// <summary>
    /// Safely detect an unfinished vanilla rich-text color prefix that was
    /// prepended to EXACTLY the text previously generated by our addon.
    /// Never strip arbitrary player-authored text or rich-text tags.
    /// </summary>
    public static bool IsKnownFormattingPrefixOf(string current, string generated)
    {
        if (string.IsNullOrEmpty(generated) || string.IsNullOrEmpty(current) ||
            !current.EndsWith(generated, StringComparison.Ordinal))
            return false;
        string prefix = current.Substring(0, current.Length - generated.Length);
        return prefix.Length > 0 && prefix.Length <= 80 &&
            Regex.IsMatch(prefix, @"^<color(?:\s|=)[^>]*>?$",
                RegexOptions.IgnoreCase);
    }

    public static bool IsBlankOrPlaceholder(string? raw, string? prefabDefault = null)
    {
        if (string.IsNullOrWhiteSpace(raw)) return true;
        // Valheim stores an empty custom sign as a rich-text color prefix,
        // sometimes followed by its default ellipsis. Strip formatting for
        // classification only: never strip data from saved player text.
        var text = Regex.Replace(raw, @"<[^>]*>", "").Trim();
        if (string.IsNullOrWhiteSpace(text) || text == "..." ||
            text == "…" || text == "···") return true;
        // Vanilla/other sign mods may save an unfinished rich-text color
        // prefix, such as <color="white" d>. The sign renders blank.
        if (Regex.IsMatch(text, @"^<color(?:\s|=|>|$)[^>]*>?$",
            RegexOptions.IgnoreCase)) return true;
        return !string.IsNullOrWhiteSpace(prefabDefault) &&
            string.Equals(text, Regex.Replace(prefabDefault, @"<[^>]*>", "").Trim(),
                StringComparison.Ordinal);
    }
}
